#include "terminal.hpp"
#include <algorithm>
#include <sstream>
namespace aether {
TerminalGrid::TerminalGrid(){theme(Theme{});resize(80,24);}
TerminalCell TerminalGrid::blank()const{return {U' ',inverse_?background_:foreground_,inverse_?foreground_:background_,bold_};}
void TerminalGrid::theme(const Theme& t){const auto old=theme_;theme_=t;palette_=terminalPalette(t);for(auto& c:cells_){if(c.foreground==old.foreground)c.foreground=t.foreground;if(c.background==old.background)c.background=t.background;}for(auto& row:history_)for(auto& c:row){if(c.foreground==old.foreground)c.foreground=t.foreground;if(c.background==old.background)c.background=t.background;}foreground_=t.foreground;background_=t.background;}
void TerminalGrid::resize(int columns,int rows){columns=std::clamp(columns,20,512);rows=std::clamp(rows,5,200);if(columns==columns_&&rows==rows_&&!cells_.empty())return;std::vector<TerminalCell> next(static_cast<std::size_t>(columns*rows),blank());for(int y=0;y<std::min(rows,rows_);++y)for(int x=0;x<std::min(columns,columns_);++x)if(static_cast<std::size_t>(y*columns_+x)<cells_.size())next[static_cast<std::size_t>(y*columns+x)]=cells_[static_cast<std::size_t>(y*columns_+x)];if(alternate_&&!normal_.empty()){std::vector<TerminalCell> resized(static_cast<std::size_t>(columns*rows),blank());for(int y=0;y<std::min(rows,rows_);++y)for(int x=0;x<std::min(columns,columns_);++x)resized[static_cast<std::size_t>(y*columns+x)]=normal_[static_cast<std::size_t>(y*columns_+x)];normal_=std::move(resized);}columns_=columns;rows_=rows;cells_=std::move(next);x_=std::clamp(x_,0,columns_-1);y_=std::clamp(y_,0,rows_-1);top_=0;bottom_=rows_-1;wrap_=false;}
void TerminalGrid::scroll(int direction){if(direction>0){if(top_==0&&bottom_==rows_-1&&!alternate_){history_.emplace_back(cells_.begin(),cells_.begin()+columns_);if(history_.size()>2000)history_.pop_front();}for(int y=top_;y<bottom_;++y)std::copy_n(cells_.begin()+(y+1)*columns_,columns_,cells_.begin()+y*columns_);std::fill_n(cells_.begin()+bottom_*columns_,columns_,blank());}else{for(int y=bottom_;y>top_;--y)std::copy_n(cells_.begin()+(y-1)*columns_,columns_,cells_.begin()+y*columns_);std::fill_n(cells_.begin()+top_*columns_,columns_,blank());}}
void TerminalGrid::newline(){wrap_=false;if(y_==bottom_)scroll(1);else y_=std::min(rows_-1,y_+1);}
void TerminalGrid::put(char32_t ch){if(wrap_){x_=0;newline();}cells_[static_cast<std::size_t>(y_*columns_+x_)]={ch,inverse_?background_:foreground_,inverse_?foreground_:background_,bold_};if(x_==columns_-1)wrap_=true;else ++x_;}
void TerminalGrid::codepoint(char32_t ch){if(ch==U'\r'){x_=0;wrap_=false;}else if(ch==U'\n')newline();else if(ch==U'\b'){x_=std::max(0,x_-1);wrap_=false;}else if(ch==U'\t'){const int target=std::min(columns_-1,((x_/8)+1)*8);while(x_<target)put(U' ');}else if(ch>=32&&ch!=127)put(ch);}
void TerminalGrid::csi(char final){bool priv=!escape_.empty()&&escape_[0]=='?';std::string text=priv?escape_.substr(1):escape_;std::vector<int> p;int value=0;for(char c:text){if(c>='0'&&c<='9')value=std::min(100000,value*10+c-'0');else if(c==';'||c==':'){p.push_back(value);value=0;}}p.push_back(value);auto arg=[&](std::size_t n,int fallback=1){return n<p.size()&&p[n]?p[n]:fallback;};auto at=[&](int x,int y){x_=std::clamp(x,0,columns_-1);y_=std::clamp(y,0,rows_-1);wrap_=false;};const int begin=y_*columns_,cursor=begin+x_;
 if(final=='A')at(x_,y_-arg(0));else if(final=='B'||final=='e')at(x_,y_+arg(0));else if(final=='C'||final=='a')at(x_+arg(0),y_);else if(final=='D')at(x_-arg(0),y_);else if(final=='E')at(0,y_+arg(0));else if(final=='F')at(0,y_-arg(0));else if(final=='G'||final=='`')at(arg(0)-1,y_);else if(final=='H'||final=='f')at(arg(1)-1,arg(0)-1);else if(final=='d')at(x_,arg(0)-1);
 else if(final=='J'){if(p[0]==2)std::fill(cells_.begin(),cells_.end(),blank());else if(p[0]==3)history_.clear();else if(p[0]==1)std::fill(cells_.begin(),cells_.begin()+cursor+1,blank());else std::fill(cells_.begin()+cursor,cells_.end(),blank());}
 else if(final=='K'){if(p[0]==2)std::fill_n(cells_.begin()+begin,columns_,blank());else if(p[0]==1)std::fill_n(cells_.begin()+begin,x_+1,blank());else std::fill(cells_.begin()+cursor,cells_.begin()+begin+columns_,blank());}
 else if(final=='s'){savedX_=x_;savedY_=y_;}else if(final=='u')at(savedX_,savedY_);
 else if(final=='r'){top_=std::clamp(arg(0)-1,0,rows_-1);bottom_=std::clamp(arg(1,rows_)-1,top_,rows_-1);at(0,0);}
 else if(final=='S'||final=='T'){for(int n=0;n<std::min(arg(0),rows_);++n)scroll(final=='S'?1:-1);}
 else if(final=='P'||final=='@'){int count=std::min(arg(0),columns_-x_);auto first=cells_.begin()+cursor,last=cells_.begin()+begin+columns_;if(final=='P'){std::move(first+count,last,first);std::fill(last-count,last,blank());}else{std::move_backward(first,last-count,last);std::fill(first,first+count,blank());}}
 else if(final=='X')std::fill_n(cells_.begin()+cursor,std::min(arg(0),columns_-x_),blank());
 else if(final=='L'||final=='M'){const auto prior=top_;top_=std::clamp(y_,top_,bottom_);for(int n=0;n<std::min(arg(0),bottom_-top_+1);++n)scroll(final=='L'?-1:1);top_=prior;}
 else if(final=='h'||final=='l'){for(int n:p){if(priv&&n==1)applicationCursor=final=='h';if(priv&&n==25)cursorVisible=final=='h';if(priv&&n==2004)bracketedPaste=final=='h';if(priv&&(n==1049||n==47||n==1047)){if(final=='h'&&!alternate_){normal_=cells_;normalX_=x_;normalY_=y_;alternate_=true;std::fill(cells_.begin(),cells_.end(),blank());at(0,0);}else if(final=='l'&&alternate_){if(normal_.size()==cells_.size())cells_=std::move(normal_);alternate_=false;at(normalX_,normalY_);}}}}
 else if(final=='n'&&p[0]==6&&response_.size()<65500)response_+="\x1b["+std::to_string(y_+1)+";"+std::to_string(x_+1)+"R";
 else if(final=='c'&&response_.size()<65500)response_+="\x1b[?1;2c";
 else if(final=='m'){auto indexed=[&](int v){v=std::clamp(v,0,255);if(v<16)return palette_[static_cast<std::size_t>(v)];if(v>=232){auto k=static_cast<std::uint32_t>(8+(v-232)*10);return (k<<16)|(k<<8)|k;}v-=16;auto c=[](int n){return static_cast<std::uint32_t>(n?55+n*40:0);};return(c(v/36)<<16)|(c((v/6)%6)<<8)|c(v%6);};for(std::size_t n=0;n<p.size();++n){int v=p[n];if(v==0){foreground_=theme_.foreground;background_=theme_.background;bold_=false;inverse_=false;}else if(v==1)bold_=true;else if(v==22)bold_=false;else if(v==7)inverse_=true;else if(v==27)inverse_=false;else if(v==39)foreground_=theme_.foreground;else if(v==49)background_=theme_.background;else if(v>=30&&v<=37)foreground_=palette_[static_cast<std::size_t>(v-30)];else if(v>=40&&v<=47)background_=palette_[static_cast<std::size_t>(v-40)];else if(v>=90&&v<=97)foreground_=palette_[static_cast<std::size_t>(v-90+8)];else if(v>=100&&v<=107)background_=palette_[static_cast<std::size_t>(v-100+8)];else if((v==38||v==48)&&n+2<p.size()){auto& color=v==38?foreground_:background_;if(p[n+1]==5){color=indexed(p[n+2]);n+=2;}else if(p[n+1]==2&&n+4<p.size()){color=(static_cast<std::uint32_t>(std::clamp(p[n+2],0,255))<<16)|(static_cast<std::uint32_t>(std::clamp(p[n+3],0,255))<<8)|static_cast<std::uint32_t>(std::clamp(p[n+4],0,255));n+=4;}}}}
}
void TerminalGrid::feed(std::string_view bytes){for(unsigned char c:bytes){if(state_==3){if(c==7){state_=0;escape_.clear();}else if(c==27)state_=4;continue;}if(state_==4){state_=c=='\\'?0:3;continue;}if(state_==1){if(c=='['){state_=2;escape_.clear();}else if(c==']'||c=='P'||c=='^'||c=='_'){state_=3;escape_.clear();}else{state_=0;if(c=='7'){savedX_=x_;savedY_=y_;}else if(c=='8'){x_=std::clamp(savedX_,0,columns_-1);y_=std::clamp(savedY_,0,rows_-1);}else if(c=='D')newline();else if(c=='M'){if(y_==top_)scroll(-1);else y_=std::max(0,y_-1);}else if(c=='c'){std::fill(cells_.begin(),cells_.end(),blank());x_=y_=0;top_=0;bottom_=rows_-1;}}continue;}if(state_==2){if(c>=0x40&&c<=0x7E){csi(static_cast<char>(c));state_=0;escape_.clear();}else if(escape_.size()<512)escape_+=static_cast<char>(c);else{state_=0;escape_.clear();}continue;}if(c==27){state_=1;remaining_=0;continue;}if(remaining_){if((c&0xC0)==0x80){utf_=(utf_<<6)|(c&0x3F);if(--remaining_==0)codepoint(utf_>=minimum_&&utf_<=0x10FFFF&&!(utf_>=0xD800&&utf_<=0xDFFF)?utf_:0xFFFD);continue;}remaining_=0;codepoint(0xFFFD);}if(c<128)codepoint(c);else if((c&0xE0)==0xC0){utf_=c&0x1F;remaining_=1;minimum_=0x80;}else if((c&0xF0)==0xE0){utf_=c&0x0F;remaining_=2;minimum_=0x800;}else if((c&0xF8)==0xF0){utf_=c&7;remaining_=3;minimum_=0x10000;}else codepoint(0xFFFD);}}
std::u32string TerminalGrid::plainText()const{std::u32string s;auto row=[&](const auto& cells){std::u32string line;for(const auto& c:cells)line+=c.glyph;while(!line.empty()&&line.back()==U' ')line.pop_back();s+=line+U'\n';};for(const auto& h:history_)row(h);for(int y=0;y<rows_;++y){std::vector<TerminalCell> cells(cells_.begin()+y*columns_,cells_.begin()+(y+1)*columns_);row(cells);}return s;}
}
